// Standard failure payload.
// The Error Trigger payload has TWO shapes (native-node-notes.md):
//  A) the workflow ran and a node failed  -> { execution: {...}, workflow: {...} }
//  B) the workflow's own TRIGGER failed   -> { trigger: { error: {name, cause, timestamp} }, workflow }
// Branch on which one is present - do not assume `execution` exists.
const j = $input.first().json || {};
const now = Date.now();
const isTriggerFailure = !j.execution && !!j.trigger;

const err = isTriggerFailure
  ? (j.trigger.error || {})
  : ((j.execution && j.execution.error) || {});

const payload = {
  activity_name: 'n8n.error.handler',
  failure_kind: isTriggerFailure ? 'trigger_activation' : 'execution',
  workflow_id: (j.workflow && j.workflow.id) || null,
  workflow_name: (j.workflow && j.workflow.name) || null,
  execution_id: (j.execution && j.execution.id) || null,
  execution_url: (j.execution && j.execution.url) || null,
  execution_mode: (j.execution && j.execution.mode) || null,
  retry_of: (j.execution && j.execution.retryOf) || null,
  last_node_executed: (j.execution && j.execution.lastNodeExecuted) || null,
  error_name: err.name || null,
  error_message: err.message || null,
  error_cause: err.cause ? String(err.cause) : null,
  error_stack: err.stack || null,
  // TEMPORAL MANDATE: the failure timestamp rides through too.
  failed_at_epoch_ms: Number(
    (j.trigger && j.trigger.error && j.trigger.error.timestamp) || now),
  reported_at_epoch_ms: now,
  reported_at_iso: new Date(now).toISOString(),
};

payload.title = '[n8n FAILURE] ' + (payload.workflow_name || 'unknown workflow');
payload.text = payload.title + '\n' +
  'kind: ' + payload.failure_kind + '\n' +
  'node: ' + (payload.last_node_executed || 'n/a') + '\n' +
  'error: ' + (payload.error_message || payload.error_name || 'unknown') + '\n' +
  'execution: ' + (payload.execution_url || 'n/a') + '\n' +
  'at: ' + payload.reported_at_iso;

return [{ json: payload }];
